// Package fdtest provides test helpers for working with file descriptors across exec.
package fdtest

import (
	"syscall"
)

// Exists returns true if fd is a valid file descriptor.
func Linux_Exists(fd uintptr) bool {
	var s syscall.Linux_Stat_t
	err := syscall.Linux_Fstat(int(fd), &s)
	return err != syscall.Linux_EBADF
}
